      "٢. رفض العرب المشروع رفضاً قاطعاً؛ لأنه سلب أخصب أراضي البلاد ومنحها لليهود المقيمين حديثاً وشرعن طرد العرب من قراهم.",
      "٣. أشعل هذا الرفض المرحلة الثانية المسلحة من الثورة الكبرى والتي كبدت الاحتلال خسائر فادحة."
